const fs=require("fs");
const dir="C:/Users/User/.claude/projects/C--Users-User-Dropbox-UIUC-2026-Fall-CS-409-Art-of-Web-Programming-mp0";
const names=new Map();
for(const f of fs.readdirSync(dir).filter(x=>x.endsWith(".jsonl"))){
 for(const line of fs.readFileSync(dir+"/"+f,"utf8").split("\n")){
  if(!line.trim())continue; let r; try{r=JSON.parse(line)}catch{continue}
  const m=r.message; if(!m||!Array.isArray(m.content))continue;
  for(const b of m.content){
    if(b.type==="tool_use") names.set(b.id,b.name);
    if(b.type==="tool_result"){
      const n=names.get(b.tool_use_id)||"?";
      if(n==="AskUserQuestion"||n==="Skill"){
        console.log("TOOL:",n,"| result keys:",Object.keys(b).join(","));
        console.log("  content:",JSON.stringify(b.content).slice(0,400));
      }
    }
  }
  // shape of the skill-dump user record
  if(r.type==="user"&&Array.isArray(m.content)&&m.content.some(b=>b.type==="text"&&b.text.length>100000)){
    console.log("SKILL-DUMP RECORD keys:",Object.keys(r).join(","));
    console.log("  isMeta:",r.isMeta,"isSidechain:",r.isSidechain,"promptSource:",r.promptSource,"origin:",r.origin,"userType:",r.userType);
  }
 }
}'

