Bash: cd "/c/Users/User/Dropbox/UIUC/2026 Fall/CS 409 Art of Web Programming/mp0" && node -e '
const fs=require("fs");
const t=fs.readFileSync("llm_logs.csv","utf8");
// strict RFC4180 parser to prove the file is well-formed
function parse(s){const rows=[];let row=[],f="",q=false;
 for(let i=0;i<s.length;i++){const c=s[i];
  if(q){ if(c===String.fromCharCode(34)){ if(s[i+1]===String.fromCharCode(34)){f+=String.fromCharCode(34);i++;} else q=false;} else f+=c; }
  else if(c===String.fromCharCode(34)) q=true;
  else if(c===",") {row.push(f);f="";}
  else if(c==="\n"){row.push(f);f="";rows.push(row);row=[];}
  else f+=c;}
 if(f||row.length){row.push(f);rows.push(row);}
 return rows;}
const rows=parse(t);
console.log("parsed rows (incl header):",rows.length);
const bad=rows.filter(r=>r.length!==5);
console.log("rows with wrong column count:",bad.length);
console.log("header:",rows[0].join(" | "));
console.log();
const counts={};for(const r of rows.slice(1)) counts[r[3]]=(counts[r[3]]||0)+1;
console.log("role counts:",JSON.stringify(counts));
console.log();
for(const r of rows.slice(1)) console.log(`t${r[2]} ${r[3].padEnd(9)} ${JSON.stringify(r[4].slice(0,95))}`);
'

