const ok=[],bad=[];
const t=(cond,msg)=>(cond?ok:bad).push(msg);

t(/<img\b/.test(html), "has <img>");
t(/<a\b[^>]*href=/.test(html), "has <a> with href");
t(/<p\b/.test(html), "has <p>");
t(/<h[1-6]\b/.test(html), "has heading");
