const fs=require("fs");
const files={ "src/index.html":fs.readFileSync("src/index.html","utf8"),
              "build/index.html":fs.readFileSync("build/index.html","utf8") };
const css=fs.readFileSync("src/css/main.css","utf8");
const bundle=fs.readFileSync("build/bundle.js","utf8");
let fail=0;
const check=(rule,pass,detail)=>{ if(!pass)fail++; console.log(`  [${pass?"x":" "}] ${detail}`); };

console.log("RULE 1 - No use of any library");
const pkg=JSON.parse(fs.readFileSync("package.json","utf8"));
check(1,Object.keys(pkg.dependencies||{}).length===0,"package.json has zero runtime dependencies");
const imports=[...fs.readFileSync("src/index.js","utf8").matchAll(/require\((.+?)\)/g)].map(m=>m[1]);
check(1,imports.every(i=>i.includes("./")),`all JS imports are relative to own files: ${imports.join(" ")}`);
const libs=["jquery","jQuery","React","angular","Vue","bootstrap","lodash","_.each","axios"];
const found=libs.filter(l=>bundle.includes(l));
check(1,found.length===0,`no library signatures in deployed bundle (checked: ${libs.length} common libs)`);
for(const [n,h] of Object.entries(files))
  check(1,!/<(link|script)[^>]+(cdn|unpkg|cdnjs|jsdelivr|googleapis)/i.test(h),`${n}: no CDN <link>/<script>`);

console.log("\nRULE 2 - No inline styling");
for(const [n,h] of Object.entries(files)){
  check(1,!/\sstyle\s*=/.test(h),`${n}: no style= attribute`);
  check(1,!/<style[\s>]/i.test(h),`${n}: no <style> block authored in HTML`);
}
check(1,css.trim().length>0,"all styling lives in src/css/main.css");

console.log("\nRULE 3 - No inline script tags");
