/* Raymond Burt - CS 409 MP 0
   Every style lives in this file; the HTML carries no inline styling.
   Layout follows the assignment's reference card: a flat, square-cornered
   block that takes a share of the window, with the content sitting at the top. */

:root {
  --page-bg: #ffffff;
  --card-bg: #13294b;                      /* Illini blue */
  --text: #f4f6fa;
  --text-muted: #c3ccdc;
  --accent: #ff7a29;                       /* Illini orange */
  --accent-hover: #ffa062;
  --rule: rgba(244, 246, 250, 0.18);
}

* {
  box-sizing: border-box;
}

body {
  margin: 0;
  padding: 38px 20px;
  background-color: var(--page-bg);
  font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, Helvetica, Arial, sans-serif;
  line-height: 1.6;
  color: var(--text);
}

.card {
  width: 63%;                              /* the reference card's share of the window */
  min-height: 60vh;                        /* open space below the text grows with the window */
  margin: 0 auto;
  padding: 16px;
  background-color: var(--card-bg);
  text-align: center;
}

/* Below tablet width a 63% column is too cramped to read. */
@media (max-width: 700px) {
  .card {
    width: 100%;
  }
}

.card__photo {
  display: block;
  width: 150px;
  height: 150px;
  margin: 0 auto 24px;
  object-fit: cover;                       /* fills the 150px box without stretching */
}

.card__name {
  margin: 0 0 6px;
  font-size: 1.75rem;
  letter-spacing: 0.01em;
}

.card__subtitle {
  margin: 0 0 10px;
  font-size: 0.8rem;
  font-weight: 600;
  text-transform: uppercase;
  letter-spacing: 0.09em;
  color: var(--text-muted);
}

.card__email {
  margin: 0 0 22px;
  font-size: 0.95rem;
  font-style: italic;
}

.card__email a {
  color: var(--text-muted);
  text-decoration: none;
}

.card__email a:hover,
.card__email a:focus {
  color: var(--accent);
  text-decoration: underline;
}

